"""Reading the three text files."""

import datetime
import re
from decimal import Decimal

from .model import Movement, Order, ParseError, Product, counting_order

WS = " \t"

_SKU = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_PRICE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
_UINT = re.compile(r"[0-9]+")
_DATE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_QTY = re.compile(r"[+-]?[0-9]+")
_ORDER_ID = re.compile(r"[Ss][Oo]-([0-9]+)")
_ITEM = re.compile(r"([A-Za-z]{2,4}-[0-9]{3})\*([0-9]+)")
_SEP = re.compile(r"[ \t]+")

TAX_RATES = ("standard", "reduced", "zero")


def split_lines(text):
    """Strip one BOM, split on LF only, drop one trailing CR per line.

    Returns ``(line_number, line)`` pairs for every line, blank or not.
    """
    if text.startswith("﻿"):
        text = text[1:]
    out = []
    for number, line in enumerate(text.split("\n"), 1):
        if line.endswith("\r"):
            line = line[:-1]
        out.append((number, line))
    return out


def data_lines(text):
    """Like split_lines but without blank lines and ``#`` comment lines."""
    for number, line in split_lines(text):
        body = line.strip(WS)
        if not body or body.startswith("#"):
            continue
        yield number, line


def parse_date(text):
    """A ``YYYY-MM-DD`` date that exists, else ``None``."""
    m = _DATE.fullmatch(text)
    if not m:
        return None
    try:
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        return None


def _int(text, number):
    try:
        return int(text)
    except ValueError:
        raise ParseError(number, "number too large: %s..." % text[:20])


def _is_sku(text):
    return _SKU.fullmatch(text) is not None


def parse_catalog(text):
    """Return ``{SKU: Product}`` from the text of ``catalog.txt``."""
    catalog = {}
    for number, line in data_lines(text):
        fields = [f.strip(WS) for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(
                number, "expected 4 or 5 fields separated by '|', found %d" % len(fields)
            )
        sku, name, price, reorder = fields[:4]
        tax = fields[4].lower() if len(fields) == 5 else "standard"
        if not _is_sku(sku):
            raise ParseError(number, "bad SKU %r" % sku)
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if not name:
            raise ParseError(number, "empty name")
        if not _PRICE.fullmatch(price):
            raise ParseError(number, "bad price %r" % price)
        value = Decimal(price)
        if value < Decimal("0.01"):
            raise ParseError(number, "price must be at least 0.01")
        if not _UINT.fullmatch(reorder):
            raise ParseError(number, "bad reorder level %r" % reorder)
        if tax not in TAX_RATES:
            raise ParseError(number, "bad tax %r" % fields[4])
        catalog[sku] = Product(sku, name, value, _int(reorder, number), tax)
    return catalog


def check_never_negative(movements):
    """Raise ParseError at the first movement that takes stock below zero."""
    balance = {}
    for m in counting_order(movements):
        balance[m.sku] = balance.get(m.sku, 0) + m.quantity
        if balance[m.sku] < 0:
            raise ParseError(m.line, "stock of %s would go below zero" % m.sku)


def parse_movements(text, catalog):
    """Return the movements of ``movements.txt`` in file order."""
    moves = []
    for number, line in data_lines(text):
        body = line.strip(WS)
        parts = _SEP.split(body, 3)
        if len(parts) < 3:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date_s, sku, qty_s = parts[:3]
        note = parts[3].strip(WS) if len(parts) == 4 else ""
        date = parse_date(date_s)
        if date is None:
            raise ParseError(number, "bad date %r" % date_s)
        if not _is_sku(sku) or sku.upper() not in catalog:
            raise ParseError(number, "unknown SKU %r" % sku)
        if not _QTY.fullmatch(qty_s):
            raise ParseError(number, "bad quantity %r" % qty_s)
        qty = _int(qty_s, number)
        if qty == 0:
            raise ParseError(number, "quantity must not be zero")
        moves.append(Movement(date, sku.upper(), qty, note, number))
    check_never_negative(moves)
    return moves


def parse_orders(text, catalog):
    """Return the orders of ``orders.txt`` in file order."""
    orders = []
    seen = set()
    for number, line in data_lines(text):
        tokens = _SEP.split(line.strip(WS))
        if len(tokens) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES")
        id_s, date_s, customer, lines_s = tokens
        m = _ORDER_ID.fullmatch(id_s)
        if not m:
            raise ParseError(number, "bad order number %r" % id_s)
        order_id = "SO-" + m.group(1)
        if order_id in seen:
            raise ParseError(number, "duplicate order %s" % order_id)
        date = parse_date(date_s)
        if date is None:
            raise ParseError(number, "bad date %r" % date_s)
        lines = []
        used = set()
        for item in lines_s.split(","):
            im = _ITEM.fullmatch(item)
            if not im:
                raise ParseError(number, "bad order line %r" % item)
            sku = im.group(1).upper()
            if sku not in catalog:
                raise ParseError(number, "unknown SKU %r" % im.group(1))
            if sku in used:
                raise ParseError(number, "SKU %s repeated in order" % sku)
            qty = _int(im.group(2), number)
            if qty < 1:
                raise ParseError(number, "quantity must be at least 1")
            used.add(sku)
            lines.append((sku, qty))
        seen.add(order_id)
        orders.append(Order(order_id, date, customer, lines, number))
    return orders
"""Stock levels, low-stock list, history and appending movements."""

from .model import counting_order
from .parse import parse_movements


def stock_levels(catalog, movements):
    """``{SKU: on hand}`` for every catalogue product (zero if never moved)."""
    levels = {sku: 0 for sku in catalog}
    for m in movements:
        levels[m.sku] = levels.get(m.sku, 0) + m.quantity
    return levels


def status(onhand, reorder):
    if onhand == 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def buy_quantity(onhand, reorder):
    return max(1, 2 * reorder - onhand)


def low_list(catalog, movements):
    """``[(product, onhand, buy)]`` for low/out products, by SKU."""
    levels = stock_levels(catalog, movements)
    rows = []
    for sku in sorted(catalog):
        product = catalog[sku]
        if status(levels[sku], product.reorder) != "ok":
            rows.append((product, levels[sku], buy_quantity(levels[sku], product.reorder)))
    return rows


def history(movements, sku):
    """``[(movement, balance)]`` for one SKU in counting order."""
    balance = 0
    rows = []
    for m in counting_order(movements):
        if m.sku == sku:
            balance += m.quantity
            rows.append((m, balance))
    return rows


def format_delta(quantity):
    return "%+d" % quantity


def movement_line(date, sku, quantity, note=""):
    line = "%s %s %s" % (date, sku, format_delta(quantity))
    return line + " " + note if note else line


def append_text(existing, new_lines):
    """The text to add to ``existing`` so it gains ``new_lines``."""
    prefix = "\n" if existing and not existing.endswith("\n") else ""
    return prefix + "".join(line + "\n" for line in new_lines)


def validate_append(existing, new_lines, catalog):
    """Parse existing + new lines by the normal rules; raises ParseError."""
    return parse_movements(existing + append_text(existing, new_lines), catalog)
"""Exact-to-the-penny pricing. All arithmetic is on whole pennies (ints)."""

import dataclasses
from decimal import Decimal
from typing import List

TAX_PERCENT = {"standard": 20, "reduced": 5, "zero": 0}


@dataclasses.dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclasses.dataclass(frozen=True)
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def _pennies(amount):
    """Whole pennies of a Decimal with at most two decimal places."""
    sign, digits, exponent = Decimal(amount).as_tuple()
    n = int("".join(map(str, digits)) or "0")
    shift = exponent + 2
    n = n * 10 ** shift if shift >= 0 else n // 10 ** (-shift)
    return -n if sign else n


def _money(pennies):
    sign = "-" if pennies < 0 else ""
    pennies = abs(pennies)
    return Decimal("%s%d.%02d" % (sign, pennies // 100, pennies % 100))


def _percent(pennies, percent):
    """``percent`` % of ``pennies`` rounded half up to a penny."""
    return (pennies * percent + 50) // 100


def _share_out(discount, nets):
    """Share ``discount`` pennies over ``nets`` pro rata, to the penny."""
    total = sum(nets)
    if discount == 0 or total == 0:
        return [0] * len(nets)
    shares = [discount * n // total for n in nets]
    remainders = [discount * n % total for n in nets]
    left = discount - sum(shares)
    ranked = sorted(range(len(nets)), key=lambda i: (-remainders[i], i))
    for i in ranked[:left]:
        shares[i] += 1
    return shares


def price_order(order, catalog):
    """Price a whole order; see the six steps in the specification."""
    gross, discount, net = [], [], []
    for sku, quantity in order.lines:
        g = quantity * _pennies(catalog[sku].price)
        if quantity >= 50:
            d = _percent(g, 10)
        elif quantity >= 10:
            d = _percent(g, 5)
        else:
            d = 0
        gross.append(g)
        discount.append(d)
        net.append(g - d)
    subtotal = sum(net)
    order_discount = _percent(subtotal, 3) if subtotal >= 50000 else 0
    shares = _share_out(order_discount, net)
    tax = 0
    for (sku, _), n, share in zip(order.lines, net, shares):
        tax += _percent(n - share, TAX_PERCENT[catalog[sku].tax])
    lines = [
        QuoteLine(sku, quantity, _money(_pennies(catalog[sku].price)),
                  _money(g), _money(-d), _money(n))
        for (sku, quantity), g, d, n in zip(order.lines, gross, discount, net)
    ]
    return Quote(
        lines,
        _money(subtotal),
        _money(-order_discount),
        _money(tax),
        _money(subtotal - order_discount + tax),
    )
"""Shipping, invoicing and the report."""

import dataclasses
from decimal import Decimal

from .model import counting_order
from .pricing import price_order


def shipped_so_far(order, movements):
    """Units already shipped per order line, capped at the ordered quantity."""
    note = "order " + order.id
    sent = {}
    for m in movements:
        if m.quantity < 0 and m.note == note:
            sent[m.sku] = sent.get(m.sku, 0) - m.quantity
    return [min(sent.get(sku, 0), qty) for sku, qty in order.lines]


def available_on(movements, sku, date):
    """Most that can leave on ``date`` without any later balance going below 0."""
    balance = 0
    best = None
    for m in counting_order(movements):
        if m.sku != sku:
            continue
        balance += m.quantity
        if m.date > date:
            best = balance if best is None else min(best, balance)
    at_date = sum(m.quantity for m in movements if m.sku == sku and m.date <= date)
    if best is not None:
        at_date = min(at_date, best)
    return max(0, at_date)


def fulfil_plan(order, movements, date):
    """Units to ship now per order line."""
    shipped = shipped_so_far(order, movements)
    plan = []
    for (sku, qty), done in zip(order.lines, shipped):
        plan.append(min(qty - done, available_on(movements, sku, date)))
    return plan


def order_status(order, shipped):
    owed = [qty - done for (_, qty), done in zip(order.lines, shipped)]
    if not any(owed):
        return "complete"
    if not any(shipped):
        return "open"
    return "partial"


def shipped_order(order, shipped):
    """The order restricted to what shipped, or ``None`` if nothing did."""
    lines = [(sku, n) for (sku, _), n in zip(order.lines, shipped) if n > 0]
    if not lines:
        return None
    return dataclasses.replace(order, lines=lines)


def _sort_key(order):
    digits = order.id[3:]
    stripped = digits.lstrip("0")
    return (order.date, len(stripped), stripped, digits)


def report_rows(orders, movements, catalog):
    rows = []
    for order in sorted(orders, key=_sort_key):
        shipped = shipped_so_far(order, movements)
        quote = price_order(order, catalog)
        sent = shipped_order(order, shipped)
        invoiced = price_order(sent, catalog).total if sent else None
        rows.append({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "status": order_status(order, shipped),
            "ordered": sum(q for _, q in order.lines),
            "shipped": sum(shipped),
            "quoted": quote.total,
            "invoiced": invoiced if invoiced is not None else Decimal("0.00"),
        })
    return rows

