"""The ``stockroom`` command. Hand-rolled argument handling on purpose."""

import csv
import io
import json
import os
import re
import sys

from . import orders as orders_mod
from . import shelves
from .model import ParseError
from .parse import parse_catalog, parse_date, parse_movements, parse_orders
from .pricing import price_order

PROG = "stockroom"
_UINT = re.compile(r"[0-9]+")
_ORDER_ARG = re.compile(r"[Ss][Oo]-([0-9]+)")
_SKU_ARG = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")

# command -> (files read, positional count(s), options)
COMMANDS = {
    "stock": ("cm", (0,), ("--json",)),
    "low": ("cm", (0,), ("--json",)),
    "history": ("cm", (1,), ("--json",)),
    "receive": ("cm", (3, 4), ()),
    "ship": ("cm", (3, 4), ()),
    "quote": ("co", (1,), ("--json",)),
    "fulfil": ("cmo", (2,), ()),
    "invoice": ("cmo", (1,), ("--json",)),
    "report": ("cmo", (0,), ("--format",)),
}
FREE_FORM = ("receive", "ship", "fulfil")


class Usage(Exception):
    """Wrong command line: exit 2."""


class ReadFailure(Exception):
    """File cannot be read: exit 2."""


class Refusal(Exception):
    """Data mistake or refused request: exit 1."""


def _parse_command_line(args):
    directory = None
    rest = []
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dir":
            if i + 1 >= len(args):
                raise Usage("option --dir needs a value")
            directory = args[i + 1]
            i += 2
            continue
        if a.startswith("--dir="):
            directory = a[len("--dir="):]
            i += 1
            continue
        rest.append(a)
        i += 1
    if directory is not None and directory == "":
        raise Usage("option --dir needs a value")
    if not rest:
        raise Usage("no command given")
    command, rest = rest[0], rest[1:]
    if command not in COMMANDS:
        raise Usage("unknown command %r" % command)
    _, counts, options = COMMANDS[command]
    positional = []
    flags = {}
    if command in FREE_FORM:
        positional = rest
    else:
        i = 0
        while i < len(rest):
            a = rest[i]
            if a == "--json" and a in options:
                flags["json"] = True
            elif "--format" in options and (a == "--format" or a.startswith("--format=")):
                if a == "--format":
                    if i + 1 >= len(rest):
                        raise Usage("option --format needs a value")
                    value = rest[i + 1]
                    i += 1
                else:
                    value = a[len("--format="):]
                if value not in ("text", "csv", "json"):
                    raise Usage("bad value for --format: %r" % value)
                flags["format"] = value
            elif a.startswith("-"):
                raise Usage("unknown option %r" % a)
            else:
                positional.append(a)
            i += 1
    if len(positional) not in counts:
        raise Usage("wrong number of arguments for %s" % command)
    if command in ("receive", "ship") and parse_date(positional[0]) is None:
        raise Usage("bad date %r" % positional[0])
    if command == "fulfil" and parse_date(positional[1]) is None:
        raise Usage("bad date %r" % positional[1])
    return command, directory if directory is not None else ".", positional, flags


def _read(directory, name, required):
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise ReadFailure("%s: file not found" % name)
        return ""
    except OSError as exc:
        raise ReadFailure("%s: %s" % (name, exc.strerror or exc))
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise ReadFailure("%s: not valid UTF-8" % name)


def _parsed(name, func, *args):
    try:
        return func(*args)
    except ParseError as exc:
        raise Refusal("%s: %s" % (name, exc))


class Context:
    pass


def _load(directory, files):
    if not os.path.isdir(directory):
        raise ReadFailure("%s: no such folder" % directory)
    ctx = Context()
    ctx.directory = directory
    ctx.catalog_text = _read(directory, "catalog.txt", True)
    ctx.movements_text = _read(directory, "movements.txt", False) if "m" in files else None
    ctx.orders_text = _read(directory, "orders.txt", False) if "o" in files else None
    ctx.catalog = _parsed("catalog.txt", parse_catalog, ctx.catalog_text)
    ctx.movements = None
    ctx.orders = None
    if ctx.movements_text is not None:
        ctx.movements = _parsed("movements.txt", parse_movements, ctx.movements_text, ctx.catalog)
    if ctx.orders_text is not None:
        ctx.orders = _parsed("orders.txt", parse_orders, ctx.orders_text, ctx.catalog)
    return ctx


def _json(value):
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def _find_sku(ctx, arg):
    if _SKU_ARG.fullmatch(arg) and arg.upper() in ctx.catalog:
        return arg.upper()
    raise Refusal("unknown SKU %s" % _show(arg))


def _find_order(ctx, arg):
    m = _ORDER_ARG.fullmatch(arg)
    if m:
        wanted = "SO-" + m.group(1)
        for order in ctx.orders:
            if order.id == wanted:
                return order
    raise Refusal("unknown order %s" % _show(arg))


def _show(text):
    return "'%s'" % text.encode("utf-8", "replace").decode("utf-8")


# ---- shelves -------------------------------------------------------------

def cmd_stock(ctx, positional, flags):
    levels = shelves.stock_levels(ctx.catalog, ctx.movements)
    rows = []
    for sku in sorted(ctx.catalog):
        p = ctx.catalog[sku]
        rows.append((sku, levels[sku], shelves.status(levels[sku], p.reorder), p.name))
    if flags.get("json"):
        return _json([{"sku": s, "name": n, "onhand": o, "status": st} for s, o, st, n in rows])
    return "".join("%s %d %s %s\n" % row for row in rows)


def cmd_low(ctx, positional, flags):
    rows = shelves.low_list(ctx.catalog, ctx.movements)
    if flags.get("json"):
        return _json([
            {"sku": p.sku, "onhand": o, "reorder": p.reorder, "buy": b} for p, o, b in rows
        ])
    return "".join("%s %d %d %d\n" % (p.sku, o, p.reorder, b) for p, o, b in rows)


def cmd_history(ctx, positional, flags):
    sku = _find_sku(ctx, positional[0])
    rows = shelves.history(ctx.movements, sku)
    if flags.get("json"):
        return _json([
            {"date": m.date.isoformat(), "delta": shelves.format_delta(m.quantity),
             "balance": b, "note": m.note}
            for m, b in rows
        ])
    out = []
    for m, b in rows:
        line = "%s %s %d" % (m.date.isoformat(), shelves.format_delta(m.quantity), b)
        out.append(line + (" " + m.note if m.note else "") + "\n")
    return "".join(out)


def _append(ctx, new_lines):
    """Validate then append lines to movements.txt in a single write."""
    try:
        shelves.validate_append(ctx.movements_text, new_lines, ctx.catalog)
    except ParseError as exc:
        raise Refusal("movements.txt: %s" % exc)
    data = shelves.append_text(ctx.movements_text, new_lines).encode("utf-8")
    path = os.path.join(ctx.directory, "movements.txt")
    try:
        with open(path, "ab") as handle:
            handle.write(data)
    except OSError as exc:
        raise ReadFailure("movements.txt: %s" % (exc.strerror or exc))


def _move(sign):
    def run(ctx, positional, flags):
        date_s, sku_s, qty_s = positional[:3]
        note = positional[3] if len(positional) == 4 else ""
        sku = _find_sku(ctx, sku_s)
        if not _UINT.fullmatch(qty_s) or int(qty_s) < 1:
            raise Refusal("quantity must be a whole number of one or more, not %s" % _show(qty_s))
        if "\n" in note or "\r" in note:
            raise Refusal("note must not contain a line break")
        note = note.strip(" \t")
        try:
            note.encode("utf-8")
        except UnicodeEncodeError:
            raise Refusal("note is not valid text")
        line = shelves.movement_line(date_s, sku, sign * int(qty_s), note)
        _append(ctx, [line])
        return line + "\n"
    return run


# ---- orders --------------------------------------------------------------

def _quote_text(order, quote, prefix=""):
    out = ["%s%s %s %s\n" % (prefix, order.id, order.date.isoformat(), order.customer)]
    for q in quote.lines:
        out.append("%s %d %s %s %s %s\n" % (q.sku, q.quantity, q.unit, q.gross, q.discount, q.net))
    out.append("subtotal %s\n" % quote.subtotal)
    out.append("order discount %s\n" % quote.order_discount)
    out.append("tax %s\n" % quote.tax)
    out.append("total %s\n" % quote.total)
    return "".join(out)


def _quote_json(order, quote):
    return _json({
        "order": order.id,
        "date": order.date.isoformat(),
        "customer": order.customer,
        "lines": [
            {"sku": q.sku, "quantity": q.quantity, "unit": str(q.unit), "gross": str(q.gross),
             "discount": str(q.discount), "net": str(q.net)}
            for q in quote.lines
        ],
        "subtotal": str(quote.subtotal),
        "order_discount": str(quote.order_discount),
        "tax": str(quote.tax),
        "total": str(quote.total),
    })


def cmd_quote(ctx, positional, flags):
    order = _find_order(ctx, positional[0])
    quote = price_order(order, ctx.catalog)
    if flags.get("json"):
        return _quote_json(order, quote)
    return _quote_text(order, quote)


def cmd_fulfil(ctx, positional, flags):
    order = _find_order(ctx, positional[0])
    date = parse_date(positional[1])
    if date < order.date:
        raise Refusal("date %s is before the order date %s" % (date, order.date))
    before = orders_mod.shipped_so_far(order, ctx.movements)
    plan = orders_mod.fulfil_plan(order, ctx.movements, date)
    lines = ["%s %s -%d order %s" % (date, sku, n, order.id)
             for (sku, _), n in zip(order.lines, plan) if n > 0]
    if lines:
        _append(ctx, lines)
    after = [b + n for b, n in zip(before, plan)]
    out = ["%s shipped %d backordered %d\n" % (sku, n, qty - done)
           for (sku, qty), n, done in zip(order.lines, plan, after)]
    out.append("status %s\n" % orders_mod.order_status(order, after))
    return "".join(out)


def cmd_invoice(ctx, positional, flags):
    order = _find_order(ctx, positional[0])
    shipped = orders_mod.shipped_so_far(order, ctx.movements)
    sent = orders_mod.shipped_order(order, shipped)
    if sent is None:
        raise Refusal("nothing has shipped for %s" % order.id)
    quote = price_order(sent, ctx.catalog)
    if flags.get("json"):
        return _quote_json(sent, quote)
    return _quote_text(sent, quote, "invoice ")


def cmd_report(ctx, positional, flags):
    rows = orders_mod.report_rows(ctx.orders, ctx.movements, ctx.catalog)
    fmt = flags.get("format", "text")
    if fmt == "json":
        return _json([
            {"order": r["order"], "date": r["date"], "customer": r["customer"],
             "status": r["status"], "ordered": r["ordered"], "shipped": r["shipped"],
             "quoted": str(r["quoted"]), "invoiced": str(r["invoiced"])}
            for r in rows
        ])
    if fmt == "csv":
        buf = io.StringIO()
        writer = csv.writer(buf, lineterminator="\n")
        writer.writerow(["order", "date", "customer", "status", "ordered", "shipped",
                         "quoted", "invoiced"])
        for r in rows:
            writer.writerow([r["order"], r["date"], r["customer"], r["status"], r["ordered"],
                             r["shipped"], r["quoted"], r["invoiced"]])
        return buf.getvalue()
    return "".join(
        "%s %s %s %s %d/%d %s %s\n" % (r["order"], r["date"], r["customer"], r["status"],
                                       r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
        for r in rows
    )


HANDLERS = {
    "stock": cmd_stock, "low": cmd_low, "history": cmd_history,
    "receive": _move(+1), "ship": _move(-1),
    "quote": cmd_quote, "fulfil": cmd_fulfil, "invoice": cmd_invoice, "report": cmd_report,
}


# ---- plumbing ------------------------------------------------------------

def _stderr(message):
    data = ("%s: %s\n" % (PROG, message)).encode("utf-8", "replace")
    try:
        sys.stderr.buffer.write(data)
        sys.stderr.buffer.flush()
    except AttributeError:
        sys.stderr.write(data.decode("utf-8"))
    except (OSError, ValueError):
        pass


def _silence_stdout():
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def _stdout(text):
    if not text:
        return
    data = text.encode("utf-8", "replace")
    try:
        try:
            out = sys.stdout.buffer
        except AttributeError:
            sys.stdout.write(text)
            sys.stdout.flush()
            return
        out.write(data)
        out.flush()
    except BrokenPipeError:
        _silence_stdout()


def main(argv=None):
    args = list(sys.argv[1:] if argv is None else argv)
    try:
        command, directory, positional, flags = _parse_command_line(args)
        ctx = _load(directory, COMMANDS[command][0])
        output = HANDLERS[command](ctx, positional, flags)
    except Usage as exc:
        _stderr(str(exc))
        return 2
    except ReadFailure as exc:
        _stderr(str(exc))
        return 2
    except Refusal as exc:
        _stderr(str(exc))
        return 1
    _stdout(output)
    return 0
"""Data types shared by the parsers and the commands."""

import datetime
from dataclasses import dataclass, field
from decimal import Decimal
from typing import List, Tuple


class ParseError(ValueError):
    """A mistake in one line of a data file. ``.line`` counts from 1."""

    def __init__(self, line, reason):
        self.line = line
        self.reason = reason
        super().__init__("line %d: %s" % (line, reason))

    def __reduce__(self):
        return (ParseError, (self.line, self.reason))


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"


@dataclass(frozen=True)
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""
    # Line in the text it was parsed from (0 when built by hand).
    line: int = field(default=0, compare=False)


@dataclass(frozen=True)
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: List[Tuple[str, int]]
    line: int = field(default=0, compare=False)


def counting_order(movements):
    """Movements in the order they count: by date, same-day keeps file order."""
    return sorted(movements, key=lambda m: m.date)
